use super::*;
use crate::cn::wps::moss::app::KmoBookApi::KmoBookApi;
use serde_json::{json,Value};
fn call<T:serde::Serialize>(f:impl FnOnce()->T)->Value{match catch_unwind(AssertUnwindSafe(f)){Ok(v)=>json!({"result":"ok","value":v}),Err(e)=>{let s=e.downcast_ref::<String>().map(String::as_str).or_else(||e.downcast_ref::<&str>().copied()).unwrap_or("");let n=["NullPointerException","IllegalArgumentException","IllegalStateException","NumberFormatException","ArrayIndexOutOfBoundsException"].into_iter().find(|n|s.starts_with(n)).unwrap_or(s);json!({"result":n})}}}
#[test]
fn original_android_name_validity_chars_and_neighbor_names(){
    let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR"));let p=root.join("rewrite-review/milestones/m4-edit-save/evidence/name-validity-r0b51");let input:Value=serde_json::from_slice(&std::fs::read(p.join("inputs.json")).unwrap()).unwrap();let java:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();
    let chars:Vec<_>=(0..=u16::MAX).map(|c|FormulaParser::toStdHalfHorn(c)as u32|((FormulaParser::isValidDefinedNameFirstChar(c)as u32)<<16)|((FormulaParser::isPivotValidDefinedNameFirstChar(c)as u32)<<17)|((FormulaParser::isValidDefinedNameChar(c)as u32)<<18)).collect();
    let mut names=vec![];for name in input["names"].as_array().unwrap(){let name=name.as_str();let mut r=json!({});for(sv,key)in [(SpreadsheetVersion::EXCEL97,"EXCEL97"),(SpreadsheetVersion::EXCEL2007,"EXCEL2007")]{r[key]=json!({"valid":call(||KmoNameManager::judgeValidName(name,Some(sv))),"classify":call(||format!("{:?}",CellReference::classifyCellReference(name,sv)))});}r["change"]=call(||KmoNameManager::changeStrValid(name));names.push(r);}
    let api=KmoBookApi::KmoBookApi();assert_eq!(api.open(root.join("rewrite-review/milestones/m1-xlsx-grid-read/fixtures/basic-types.xlsx").to_str().unwrap(),None,true),1);std::thread::sleep(std::time::Duration::from_millis(1000));let book=api.book();let sheet=book.getActiveSheet();for c in input["grid"].as_array().unwrap(){sheet.borrow().setCellStringValue(c["row"].as_i64().unwrap()as i32,c["col"].as_i64().unwrap()as i32,c["text"].as_str());}let mut rectangles=vec![];for r in input["rectangles"].as_array().unwrap(){let rect=KmoRect::KmoRect__bounds(r[0].as_i64().unwrap()as i32,r[1].as_i64().unwrap()as i32,r[2].as_i64().unwrap()as i32,r[3].as_i64().unwrap()as i32);rectangles.push(call(||KmoNameManager::getTopLeftName(Some(&book),Some(&rect))));}
    let actual=json!({"chars":chars,"names":names,"rectangles":rectangles});std::fs::write(p.join("rust.json"),serde_json::to_vec_pretty(&actual).unwrap()).unwrap();fn compare(a:&Value,b:&Value,path:&str){match(a,b){(Value::Object(x),Value::Object(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(k,v)in x{compare(v,y.get(k).unwrap(),&format!("{path}.{k}"));}},(Value::Array(x),Value::Array(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(i,(a,b))in x.iter().zip(y).enumerate(){compare(a,b,&format!("{path}[{i}]"));}},_=>assert_eq!(a,b,"{path}")}}compare(&actual,&java,"root");
}
